List<int> traverse(List<List<int>> graph, int node, List<int> path) {
  for (var neighbor in graph[node]) {
    if (!visited[neighbor]) {
      visited[neighbor] = true;
      path.add(neighbor);
      path = traverse(graph, neighbor, path);
    } else if (path.contains(neighbor)) {
      return path; 
    }
  }
  return path;
}

