    if (!wordBreak(s, wordDict)) {
      print("Cannot segment");
      return [];
    }

    List<String> result = [];
    List<String> path = [];

    void backtrack(int index) {
      if (index == s.length) {
        result.add(path.join(" "));
        return;
      }

      for (String word in wordDict) {
        if (s.substring(index, index + word.length) == word) {
          path.add(word);
          backtrack(index + word.length);
          path.removeLast();
        }
      }
    }

    backtrack(0);
    return result;
  }

  List<String> allSeg = allWordBreakings(s, wordDict);
  print("All possible segmentations:");
  for (String seg in allSeg) {
    print(seg);
