List<String> fn0(List<String> log) {
  final stack = <Map<String, dynamic>>[];
  final results = <String>[];

  for (final line in log) {
    final parts = line.split(' ');
    final id = parts[1];

    if (parts[0] == 'BEGIN') {
      stack.add({'id': id, 'value': 0});
    } else if (parts[0] == 'ADD') {
      final last = stack.removeLast();
      final current = stack.last;
      current['value'] = current['value']! + int.parse(parts[2]);
      stack.add(current);
    } else if (parts[0] == 'UNDO') {
      final last = stack.removeLast();
      final current = stack.last;
      current['value'] = current['value']! - last['value']!;
      stack.add(current);
    } else if (parts[0] == 'END') {
      final last = stack.removeLast();
      final current = stack.last;
      final result = (current['value'] as int) * int.parse(last['id']!);
      results.add('$id:$result');
    }
  }

  return results;
}

