    while (i < n) {
      if (pattern[j] == text[i]) {
        i++;
        j++;
      }
      if (j == m) {
        return true;
      }
      if (i < n && pattern[j] != text[i]) {
        if (j != 0) j = lps[j - 1];
        else i++;
      }
    }
    return false;
  }

