void fn0() {

  String text = "HERE IS A SIMPLE EXAMPLE";
  String pattern = "EXAMPLE";

  int n = text.length;
  int m = pattern.length;

  if (m == 0) {
    print("Pattern not found. Length of pattern must be greater than 0.");
    return;
  }

  if (m > n) {
    print("Pattern length greater than text length. Pattern not found.");
    return;
  }

  List<List<int>> dp = List.generate(n + 1, (_) => List<int>.filled(m + 1, 0));

  for (int i = 0; i <= n; i++) {
    dp[i][0] = i;
  }

  for (int j = 0; j <= m; j++) {
    dp[0][j] = j;
  }

  for (int i = 1; i <= n; i++) {
    for (int j = 1; j <= m; j++) {
      int cost = 1;

      if (text[i - 1] != pattern[j - 1]) {
        cost = cost + 1;
      }

      dp[i][j] = [dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + cost].reduce((a, b) => a < b ? a : b);
    }
  }

  List<int> result = [];
  int i = n;
  int j = m;

  while (i > 0 && j > 0) {
    if (dp[i][j] == dp[i - 1][j]) {
      i--;
    } else if (dp[i][j] == dp[i][j - 1]) {
      j--;
    } else {
      result.add(i - 1);
      i--;
      j--;
    }
  }

  if (j > 0) {
    result.add(n - 1);
  }

  if (result.isEmpty) {
    print("Pattern not found.");
  } else {
    print("Pattern found at positions: ${result.join(', ')}");
  }
}

