int nChooseK(int n, int k) {
  if (k < 0) return 0;
  if (k > n) return 0;
  if (k == 0) return 1;

  int result = 1;
  for (int i = 0; i < k; i++) {
    result = result * (n - i);
  }
  return result;
}

void generateCombinations(List<String> items, int k) {
  final int n = items.length;
  final List<String> result = List.filled(nChooseK(n, k), '');

  int i = 0;
  while (i < n) {
    if (i + k < n) {
      final List<String> current = items.sublist(i, i + k);
      result[i] = current.join(',');
      i += k;
    } else {
      final List<String> current = items.sublist(i);
      result[i] = current.join(',');
      break;
    }
  }

  for (final combination in result) {
    print(combination);
  }
}

