List<List<String>> generateCombinations(List<String> items, int k) {
  if (items.isEmpty || k <= 0 || k > items.length) {
    return <List<String>>[];
  }

  List<String> result = <String>[];
  void backtrack(int start, int remaining) {
    if (remaining == 0) {
      result.add(List<String>.from(start));
      return;
    }
    for (int i = start; i < items.length; i++) {
      String item = items[i];
      backtrack(i + 1, remaining - 1);
      backtrack(i + 1, remaining);
    }
  }

  backtrack(0, k);
  return result;
}

