    return schedule;
  }

  List<List<int>> result = [];
  for (String seat in openSeats) {
    result.add([seat.codeUnitAt(0) - 96, 0]);
  }
  result.sort((a, b) {
    int cmp = a[0].compareTo(b[0]);
    if (cmp != 0) return cmp;
    return a[1].compareTo(b[1]);
  });

  List<int> sorted = [];
  for (var row in result) {
    if (!sorted.contains(row[1])) {
      sorted.add(row[1]);
    }
  }
  sorted.sort();
  return schedule;
}

