void fn0(List<String> args) {

  if (args.length != 1) {
    print('Usage: dart run script.dart <N>');
    return;
  }

  final n = int.tryParse(args[0]);
  if (n == null || n < 0) {
    print('N must be a positive integer.');
    return;
  }

  final totalSolutions = <List<int>>[];
  void solve(int remaining, List<int> current) {
    if (remaining == 0) {
      totalSolutions.add(List.from(current));
      return;
    }
    for (var i = 1; i <= n; i++) {
      current.add(i);
      solve(remaining - 1, current);
      current.removeLast();
    }
  }

  solve(n, <int>[]);
  print('Solving N-Queens for N=$n');
  print('Total solutions: ${totalSolutions.length}');

  for (var solution in totalSolutions) {
    print('Solution ${solution.length} : ${solution.join(' ')}');
  }
}

