Map<String, int> fn0(List<int> arrivalMinutes, int maxGap) {
  if (arrivalMinutes.isEmpty) return {'pairCount': 0, 'mashupDuration': 0};

  int countPairs(int index, int currentSum) {
    if (index == arrivalMinutes.length) {
      return currentSum == 0 ? 1 : 0;
    }

    final int minutes = arrivalMinutes[index];
    final int newSum = currentSum + minutes;

    if (newSum > 60) {
      return countPairs(index + 1, 0);
    }

    final int remaining = arrivalMinutes.length - index - 1;
    final int remainingCount = countPairs(index + 1, newSum);

    if (remaining > 0) {
      final int nextIndex = index + 1;
      final int nextSum = newSum + arrivalMinutes[nextIndex];
      if (nextSum <= 60) {
        return countPairs(nextIndex, nextSum) + remainingCount;
      }
    }

    return remainingCount;
  }

  final int totalPairs = countPairs(0, 0);
  final int mashupDuration = totalPairs * maxGap;

  return {'pairCount': totalPairs, 'mashupDuration': mashupDuration};
}

