Map<String, int> fn0(List<int> songDurations, int targetMinutes) {
  int n = songDurations.length;
  if (n == 0 || targetMinutes <= 0) return {"pairCount": 0, "mashupDuration": 0};

  int targetSeconds = targetMinutes * 60;
  int totalDuration = 0;
  for (int i = 0; i < n; i++) {
    totalDuration += songDurations[i];
  }
  if (totalDuration < targetSeconds) return {"pairCount": 0, "mashupDuration": 0};

  int lo = 0;
  int hi = n - 1;
  while (lo < hi) {
    int mid = (lo + hi) ~/ 2;
    if (songDurations[mid] <= targetSeconds) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }

  int start = lo;
  int end = lo + 1;
  int pairCount = 0;
  while (end < n) {
    if (songDurations[end] > songDurations[start]) {
      pairCount++;
      start = end;
    }
    end++;
  }

  int currentTotal = songDurations.sublist(start, end).reduce((a, b) => a + b);
  int mashupDuration = currentTotal - (pairCount - 1);

  return {"pairCount": pairCount, "mashupDuration": mashupDuration};
}

