    }
  }
  int count = 0;
  for (int j = 0; j <= targetDuration; j++) {
    if (dp[n - 1][j]) {
      count++;
    }
  }
  int total = 0;
  for (int j = 0; j <= targetDuration; j++) {
    if (dp[n - 1][j]) {
      total += j;
    }
  }
  return {"pairCount": count, "mashupDuration": total};
}

