/// Quaternion class for representing 4-dimensional vectors with
/// a real part and three imaginary parts.
class Quaternion {
  final double x, y, z, w;

  const Quaternion(this.x, this.y, this.z, this.w);

  static const Quaternion zero = Quaternion(0, 0, 0, 0);

  double norm() {
    return x * x + y * y + z * z + w * w;
  }

  static Quaternion fromNormAndAngles(double norm, double thetaX, double thetaY, double thetaZ) {
    double sinThetaX = sin(thetaX);
    double sinThetaY = sin(thetaY);
    double sinThetaZ = sin(thetaZ);
    double cosTheta = cos(thetaX);
    return Quaternion(
      (x * cosTheta + y * sinThetaX * sinThetaY - z * sinThetaZ * sinThetaY) / norm,
      (y * cosTheta + z * sinThetaX * sinThetaY) / norm,
      (z * cosTheta + x * sinThetaX * sinThetaZ) / norm,
      (w * cosTheta + x * y * sinThetaZ) / norm,
    );
  }

  Quaternion conjugate() {
    return Quaternion(x, y, -z, w);
  }

  Quaternion inverse() {
    final double n = norm();
    if (n == 0) throw ArgumentError('Cannot invert zero quaternion');
    return Quaternion(
      x / n,
      y / n,
      -z / n,
      w / n,
    );
  }

  Quaternion normalized() {
    final double n = norm();
    if (n == 0) throw ArgumentError('Cannot normalize zero quaternion');
    return Quaternion(
      x / n,
      y / n,
      z / n,
      w / n,
    );
  }

  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  Quaternion operator -(Quaternion other) {
    return Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);
  }

  Quaternion operator *(double scalar) {
    return Quaternion(
      x * scalar,
      y * scalar,
      z * scalar,
      w * scalar,
    );
  }

  Quaternion operator *(Quaternion other) {
    final double ax = x, ay = y, az = z, aw = w;
    final double bx = other.x, by = other.y, bz = other.z, bw = other.w;
    return Quaternion(
      ax * other.w + bx * w,
      ay * other.w + by * w,
      az * other.w + bz * w,
      aw * other.w + bx * ay + by * az + bz * ax,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

