class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  Quaternion(this.x, this.y, this.z, this.w);

  Quaternion operator +(Quaternion other) =>
      Quaternion(x + other.x, y + other.y, z + other.z, w + other.w);

  Quaternion operator -(Quaternion other) =>
      Quaternion(x - other.x, y - other.y, z - other.z, w - other.w);

  Quaternion operator *(double scalar) =>
      Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);

  Quaternion operator *(Quaternion other) {
    double wx = x * other.w;
    double wy = y * other.w;
    double wz = z * other.w;
    double ww = other.x * w + x * other.y + y * other.z + z * other.w;

    return Quaternion(
      wx - ww,
      wy - ww,
      wz - ww,
      ww,
    );
  }

  double norm() => x * x + y * y + z * z + w * w;

  Quaternion normalized() {
    double n = norm();
    if (n == 0.0) {
      throw ArgumentError('Cannot normalize zero quaternion');
    }
    return Quaternion(x / n, y / n, z / n, w / n);
  }

  Quaternion conjugate() =>
      Quaternion(x, y, z, -w);

  Quaternion inverse() {
    double n = norm();
    if (n == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    return Quaternion(
      x / n,
      y / n,
      z / n,
      -w / n,
    );
  }

  Quaternion rotate(double theta) {
    double sinT = sin(theta);
    double cosT = cos(theta);
    return Quaternion(
      cosT * x + sinT * z,
      cosT * y + sinT * w,
      -sinT * x + cosT * z,
      -sinT * y + cosT * w,
    );
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

