class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  const Quaternion.fromList(List<double> list)
      : x = list[0],
        y = list[1],
        z = list[2],
        w = list[3];

  const Quaternion.fromUnit(double module, double angle) {
    final sin = sin(angle);
    final cos = cos(angle);
    x = (2 * sin * cos) + x;
    y = (2 * sin * cos) + y;
    z = (2 * sin * cos) + z;
    w = (1 - 2 * sin * sin) + w;
  }

  const Quaternion.zero() : this(0.0, 0.0, 0.0, 0.0);

  double norm() => sqrt(x * x + y * y + z * z + w * w);

  Quaternion normalized() =>
      Quaternion.fromUnit(norm(), atan2(sqrt(x * x + y * y), z));

  Quaternion conjugate() => Quaternion(x, y, -z, w);

  Quaternion inverse() {
    final norm = norm();
    if (norm == 0.0) {
      throw ArgumentError('Cannot invert zero quaternion');
    }
    final inv = 1 / norm;
    return Quaternion(
      x * inv,
      y * inv,
      z * inv,
      w * inv,
    );
  }

  Quaternion rotateZ(double angle) {
    final sin = sin(angle);
    final cos = cos(angle);
    final tmp = Quaternion(
      w * cos + x * sin,
      y * cos + z * sin,
      z * cos - w * sin,
      w * cos - x * sin,
    );
    return tmp - tmp.conjugate() * 0.5;
  }

  @override
  String toString() {
    return 'Quaternion($x, $y, $z, $w)';
  }
}

