class Quaternion {
  final double x;
  final double y;
  final double z;
  final double w;

  const Quaternion(this.x, this.y, this.z, this.w);

  /// Quaternion with all components normalized to 1.
  /// Uses the Gram-Schmidt orthogonalization process:
  ///   q1 = (x1, y1, z1, w1)
  ///   q2 = (x2, y2, z2, w2)
  ///   q1 * q2 = (x1 * x2 + y1 * y2 + z1 * z2 + w1 * w2,
  ///              x1 * y2 - y1 * x2,
  ///              x1 * z2 - z1 * x2,
  ///              y1 * y2 - z1 * z2)
  ///   q1 + q2 = (x1 + x2, y1 + y2, z1 + z2, w1 + w2)
  ///   q1 - q2 = (x1 - x2, y1 - y2, z1 - z2, w1 - w2)
  ///   q1 * 2 = (2 * x1, 2 * y1, 2 * z1, 2 * w1)
  ///   inverse(q) = (x, -y, -z, w)
  ///   norm(q) = sqrt(x^2 + y^2 + z^2 + w^2)
  ///   normalized(q) = (x / norm(q), y / norm(q), z / norm(q), w / norm(q))
  ///   conjugate(q) = (x, -y, -z, w)
  ///   q1.isZero ? true : false

  /// Quaternion with all components equal to 0.
  factory Quaternion(double x, double y, double z, double w) {
    if (x == 0 && y == 0 && z == 0 && w == 0) {
      return const Quaternion(0.0, 0.0, 0.0, 0.0);
    }

    /// Normalize the quaternion using Gram-Schmidt.
    final double norm = x * x + y * y + z * z + w * w;
    return Quaternion(
      x / norm,
      y / norm,
      z / norm,
      w / norm,
    );
  }

  /// Returns a normalized quaternion with all components equal to 0.
  factory Quaternion.zero() {
    return const Quaternion(0.0, 0.0, 0.0, 0.0);
  }

  const Quaternion(this.x, this.y, this.z, this.w)
      : assert(x.abs() + y.abs() + z.abs() + w.abs() == 1);

  /// Multiplies two quaternions.
  Quaternion operator *(Quaternion other) {
    final double xx = x * x;
    final double xy = x * y;
    final double xz = x * z;
    final double xw = x * w;
    final double yy = y * y;
    final double yz = y * z;
    final double yw = y * w;
    final double zz = z * z;
    final double zw = z * w;
    return Quaternion(
      xx + yy - zz - zw,
      2 * xy + zw,
      2 * xz + yw,
      2 * xw,
    );
  }

  /// Adds two quaternions.
  Quaternion operator +(Quaternion other) {
    return Quaternion(
      x + other.x,
      y + other.y,
      z + other.z,
      w + other.w,
    );
  }

  /// Subtracts two quaternions.
  Quaternion operator -(Quaternion other) {
    return Quaternion(
      x - other.x,
      y - other.y,
      z - other.z,
      w - other.w,
    );
  }

  /// Multiplies a quaternion by a scalar.
  Quaternion operator *(double scalar) {
    return Quaternion(x * scalar, y * scalar, z * scalar, w * scalar);
  }

  /// Inverts a quaternion.
  Quaternion operator ~/ {
    final double invNorm = 1.0 / x * x + 1.0 / y * y + 1.0 / z * z + 1.0 / w * w;
    return Quaternion(
      x * invNorm,
      -y * invNorm,
      -z * invNorm,
      w * invNorm,
    );
  }

  /// Calculates the Euclidean norm of the quaternion.
  double norm() {
    return sqrt(x * x + y * y + z * z + w * w);
  }

  /// Normalizes the quaternion.
  Quaternion normalized() {
    final double norm = x * x + y * y + z * z + w * w;
    return Quaternion(x / norm, y / norm, z / norm, w / norm);
  }

  /// Concatugates the quaternion.
  Quaternion conjugate() {
    return Quaternion(x, -y, -z, w);
  }

  @override
  bool get isZero => x == 0 && y == 0 && z == 0 && w == 0;

  @override
  String toString() {
    final String sign = w >= 0 ? '+' : '-';
    return 'Quaternion($x, $y, $z, $w)';
  }
}

