    if (count == 0) {
      c = 65792;
    } else if (c != d) {
      count += (65792 - c) ~/ (d - c);
    }
    count++;
  }
  return {'gcd': count, 'cycleCount': count, 'uniquePositions': endDay - startDay + 1};
}

