import 'dart:async';
import 'dart:convert';
enum UserRole { user, moderator, admin }

enum ResourceType {
  document1,
  document2,
  sensitiveData,
  userManagement,
  contentModeration,

  totalResources
}

class Role {
  final String name;
  final List<ResourceType> resources;

  Role(this.name, this.resources);
}

class AccessControl {
  final Map<String, List<ResourceType>> userPermissions;
  final Map<String, Map<ResourceType, String>> resourcePermissions;

  AccessControl(this.userPermissions, this.resourcePermissions);

  bool _hasPermission(String user, ResourceType resource, String role) {
    if (!userPermissions.containsKey(user)) return false;
    if (!resourcePermissions.containsKey(resource)) return false;

    return (userPermissions[user]!.contains(resource) &&
        resourcePermissions[resource]!.contains(role));
  }

  void _logAccessAttempt(String user, ResourceType resource, String role, String result) {
    print('[$user, $resource, $role, $result]');
  }

  void _grantAccess(String user, ResourceType resource, String role) {
    if (!_hasPermission(user, resource, role)) {
      _logAccessAttempt(user, resource, role, 'DENIED');
      return;
    }
    _logAccessAttempt(user, resource, role, 'SUCCESS');
  }

  void _denyAccess(String user, ResourceType resource, String role) {
    if (!_hasPermission(user, resource, role)) {
      _logAccessAttempt(user, resource, role, 'DENIED');
      return;
    }
    _logAccessAttempt(user, resource, role, 'DENIED');
  }

  void attemptAccess(String user, ResourceType resource) {
    String role = _inferRoleFromUser(user);
    if (_hasPermission(user, resource, role)) {
      _grantAccess(user, resource, role);
    } else {
      _denyAccess(user, resource, role);
    }
  }

  String _inferRoleFromUser(String user) {
    if (userPermissions.containsKey(user)) {
      return 'admin';
    } else if (resourcePermissions.containsKey(ResourceType.totalResources)) {
      return 'moderator';
    }
    return 'user';
  }
}

