@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {


  final Set<String> items = {'Milk', 'Bread', 'Butter'};

  final int minSupport = 2;

  final int minConfidence = 0.7;

  final Map<String, int> itemFreq = <String, int>{};

  for (final String item in items) {
    for (final int j = 1; j <= item.length; j++) {
      final String prefix = item.substring(0, j);
      final String suffix = item.substring(j);
      final Set<String> candidatePrefix = <String>{prefix};
      final Set<String> candidateSuffix = <String>{suffix};
      final List<String> candidate = <String>[...candidatePrefix, ...candidateSuffix];

      itemFreq[prefix] = (itemFreq[prefix] ?? 0) + 1;
    }
  }

  final List<List<String>> frequentItemsets = <List<String>>[
    [items.toString()],
  ];

  for (final String item in items) {
    if (itemFreq[item]! >= minSupport) {
      final List<String> current = <String>[item];
      for (final int j = 1; j <= item.length; j++) {
        final String prefix = item.substring(0, j);
        final String suffix = item.substring(j);
        final Set<String> candidatePrefix = <String>{prefix};
        final Set<String> candidateSuffix = <String>{suffix};
        final List<String> candidate = <String>[...candidatePrefix, ...candidateSuffix];

        final Map<String, int> freqCandidate = <String, int>{};
        for (final String item in candidate) {
          freqCandidate[item] = (freqCandidate[item] ?? 0) + 1;
        }

        final List<List<String>> candidateSets = <List<String>>[
          [item]
        ];

        for (final MapEntry<String, int> entry in freqCandidate.entries) {
          if (entry.value >= minSupport) {
            candidateSets.add(<String>[...entry.key, ...current]);
          }
        }

        for (final List<String> candidateSet in candidateSets) {
          if (candidateSet.length > 1) {
            for (final List<String> existing in frequentItemsets) {
              if (existing == candidateSet) {
                return;
              }
              bool allSubset = true;
              for (final String item in candidateSet) {
                if (!existing.contains(item)) {
                  allSubset = false;
                  break;
                }
              }
              if (allSubset) {
                existing.add(candidateSet.last);
              }
            }
          } else if (candidateSet.length == 1) {
            frequentItemsets.add(<String>[...candidateSet[0], ...current]);
          }
        }
      }
    }
  }

  print('Frequent Itemsets:');
  for (final List<String> itemset in frequentItemsets) {
    print('  ${itemset.join(' ')}');
  }

  final Map<String, Set<String>> assocRules = <String, Set<String>>{};

  for (final List<String> itemset in frequentItemsets) {
    if (itemset.length <= 2) {
      continue;
    }
    for (int i = 0; i < itemset.length - 1; i++) {
      for (int j = i + 1; j < itemset.length; j++) {
        final String antecedent = itemset.sublist(0, i).join(' ');
        final String consequent = itemset.sublist(i + 1).join(' ');
        assocRules[consequent] = (assocRules[consequent] ?? <String>{})..add(antecedent);
      }
    }
  }

  print('\nAssociation Rules:');
  for (final MapEntry<String, Set<String>> entry in assocRules.entries) {
    if (entry.value.length >= minConfidence) {
      final double confidence = entry.value.length / itemFreq[entry.key]!;
      print('  ${entry.key} => ${entry.value} (support: ${itemFreq[entry.key]} confidence: $confidence)');
    }
  }
}

