class Point {
  final double x;
  final double y;

  const Point(this.x, this.y);

  @override
  String toString() => 'Point($x, $y)';
}

class Rectangle {
  final double x1;
  final double y1;
  final double x2;
  final double y2;

  Rectangle(this.x1, this.y1, this.x2, this.y2);

  Rectangle.square(double centerX, double centerY, double halfWidth, double halfHeight)
      : this(centerX - halfWidth, centerY - halfHeight, centerX + halfWidth, centerY + halfHeight);

  Rectangle.fromPoints(Point p1, Point p2)
      : this(p1.x, p1.y, p2.x, p2.y);

  Rectangle.fromCenter(Point center, double halfWidth, double halfHeight)
      : this(center.x - halfWidth, center.y - halfHeight, center.x + halfWidth, center.y + halfHeight);

  Rectangle get bounds => Rectangle.fromPoints(Point(x1, y1), Point(x2, y2));

  Rectangle get right => Rectangle.fromPoints(Point(x2, y1), Point(x2, y2));

  Rectangle get bottom => Rectangle.fromPoints(Point(x1, y2), Point(x2, y2));

  Rectangle get left => Rectangle.fromPoints(Point(x1, y1), Point(x1, y2));

  Rectangle get top => Rectangle.fromPoints(Point(x1, y1), Point(x2, y1));

  double get area => (x2 - x1) * (y2 - y1);

  double get halfWidth => x2 - x1;

  double get halfHeight => y2 - y1;

  @override
  String toString() => 'Rectangle(center: ($x1, $y1), halfWidth: $halfWidth, halfHeight: $halfHeight)';
}

