    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.2],
    [9.0, 6.0],
    [8.0, 7.0],
    [2.0, 4.0],
    [5.0, 5.0],
    [5.0, 7.0],
    [3.0, 5.0],
    [7.0, 2.0],
    [3.5, 7.0],
    [4.0, 2.0],
    [3.0, 4.0],
  ];

  final int k = 3;
  final double eps = 1.0;
  final int minPts = 2;

  final clusters = List<List<double>>.generate(data.length, (_) => []);

  for (var i = 0; i < data.length; i++) {
    clusters[i] = [data[i]];
  }

  var clusterId = 0;
  var converged = false;

  while (!converged) {

    final neighbours = <List<double>>[];

    for (final point in clusters) {
      for (final cluster in clusters) {
        if (point == cluster) continue;
        final dist = (point[0] - cluster[0]).abs() + (point[1] - cluster[1]).abs();
        if (dist <= eps) {
          neighbours.add(cluster);
        }
      }
    }

    for (var i = 0; i < data.length; i++) {

      if (!neighbours.contains(clusters[i])) {
        clusters[i] = List<double>.from(neighbours);
      }
    }

    final union = <List<double>>[];
    for (final cluster in clusters) {
      if (cluster.length >= minPts) {
        union.add(cluster);
      }
    }

    if (union == clusters) {
      converged = true;
    } else {
      clusters = union;
      clusterId++;
    }
