  ];

  List<int> labels = List.generate(points.length, (i) => i);
  List<List<double>> centroids = List.generate(k, (_) => List<double>.filled(points[0].length, 0.0));

  double distance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      sum += pow(a[i] - b[i], 2);
    }
    return sqrt(sum);
  }

  bool converged = false;
  int iterations = 0;

  while (iterations < 100 && !converged) {

    converged = true;

    for (int i = 0; i < points.length; i++) {
      double minDist = double.infinity;
      int assignedCluster = -1;
      for (int j = 0; j < k; j++) {
        double dist = distance(points[i], centroids[j]);
        if (dist < minDist) {
          minDist = dist;
          assignedCluster = j;
        }
      }
      if (assignedCluster != labels[i]) {
        labels[i] = assignedCluster;
        converged = false;
      }
    }

    for (int j = 0; j < k; j++) {
      double sum = 0.0;
      int count = 0;
      for (int i = 0; i < points.length; i++) {
        if (labels[i] == j) {
          sum += points[i];
          count++;
        }
      }
      if (count > 0) {
        centroids[j] = List<double>.from(sum / count);
      }
    }

