  }

  print('Cluster $k analysis:');
  print('Converged in $iterations iteration(s).');
  for (int i = 0; i < k; i++) {
    print('Cluster $i:');
    for (int j = 0; j < points.length; j++) {
      if (labels[j] == i) {
        print('  Points: ${points[j]}');
      }
    }
    print(' centroid: ${centroids[i]}');
  }
