void fn0() {

  final rng = Random(0);

  final points = [
    [1.0, 2.0],
    [1.5, 1.5],
    [5.0, 8.0],
    [8.0, 8.0],
    [1.0, 0.5],
    [9.0, 7.0],
    [8.0, 1.0],
    [7.0, 2.0],
    [2.5, 2.5],
    [7.0, 3.5],
  ];

  final numClusters = 3;

  final result = List<List<num>>.generate(numClusters, (_) => []);

  for (var i = 0; i < points.length; i++) {
    final cluster = rng.nextInt(numClusters);
    result[cluster].add(points[i]);
  }

  final centroids = List<List<num>>.generate(numClusters, (_) => [0.0, 0.0]);

  while (true) {
    var converged = true;

    for (var i = 0; i < numClusters; i++) {
      final newCentroid = List<num>.from(centroids[i]);
      var totalX = 0.0;
      var totalY = 0.0;
      for (final point in result[i]) {
        totalX += point[0];
        totalY += point[1];
      }
      newCentroid[0] = totalX / result[i].length;
      newCentroid[1] = totalY / result[i].length;
      for (var j = 0; j < numClusters; j++) {
        if (i == j) continue;
        final dist = (newCentroid[0] - centroids[j][0]).abs() + (newCentroid[1] - centroids[j][1]).abs();
        if (dist < 1.0) {
          converged = false;
          break;
        }
      }
      centroids[i] = newCentroid;
    }

    if (converged) break;

    print('Iteration ${i + 1}:');
    for (var j = 0; j < numClusters; j++) {
      print('Cluster $j:');
      for (final point in result[j]) {
        print('  ${point[0]}, ${point[1]}');
      }
    }
    print('Converged in ${i + 1} iteration(s).');
  }
}

